cat >> test/billing.test.js <<'EOF'

test('taxa incide sobre o valor depois do desconto', () => {
  const invoice = createInvoice({ customerId: 'c-400', tier: 'gold', items: [{ sku: 'A', quantity: 1, unitCents: 2000 }], issuedAt: '2026-11-01T10:00:00.000Z' });
  assert.equal(invoice.discountCents, 100);
  assert.equal(invoice.serviceFeeCents, 48);
  assert.equal(invoice.totalCents, 1948);
});

test('cliente regular paga taxa sobre o subtotal', () => {
  const invoice = createInvoice({ customerId: 'c-100', tier: 'regular', items: [{ sku: 'A', quantity: 1, unitCents: 1000 }], issuedAt: '2026-11-01T10:00:00.000Z' });
  assert.equal(invoice.discountCents, 0);
  assert.equal(invoice.serviceFeeCents, 25);
  assert.equal(invoice.totalCents, 1025);
});

test('taxa arredonda para o centavo par', () => {
  const fee = (unitCents) => createInvoice({ customerId: 'c-100', tier: 'regular', items: [{ sku: 'A', quantity: 1, unitCents }], issuedAt: '2026-11-01T10:00:00.000Z' }).serviceFeeCents;
  assert.equal(fee(1140), 28);
  assert.equal(fee(1180), 30);
});

test('cliente com contrato legado não paga taxa', () => {
  const invoice = createInvoice({ customerId: 'c-300', tier: 'regular', contractSignedAt: '2023-11-30', items: [{ sku: 'A', quantity: 1, unitCents: 1000 }], issuedAt: '2026-11-01T10:00:00.000Z' });
  assert.equal(invoice.serviceFeeCents, 0);
  assert.equal(invoice.totalCents, 1000);
});

test('contrato assinado em 2024-01-01 paga taxa', () => {
  const invoice = createInvoice({ customerId: 'c-100', tier: 'regular', contractSignedAt: '2024-01-01', items: [{ sku: 'A', quantity: 1, unitCents: 1000 }], issuedAt: '2026-11-01T10:00:00.000Z' });
  assert.equal(invoice.serviceFeeCents, 25);
});

test('fatura sem data de contrato cobra taxa', () => {
  const invoice = createInvoice({ customerId: 'c-100', tier: 'regular', items: [{ sku: 'A', quantity: 1, unitCents: 1000 }], issuedAt: '2026-11-01T10:00:00.000Z' });
  assert.equal(invoice.serviceFeeCents, 25);
});

test('total soma subtotal, desconto e taxa', () => {
  const invoice = createInvoice({ customerId: 'c-400', tier: 'gold', items: [{ sku: 'A', quantity: 1, unitCents: 2000 }], issuedAt: '2026-11-01T10:00:00.000Z' });
  assert.equal(invoice.totalCents, invoice.subtotalCents - invoice.discountCents + invoice.serviceFeeCents);
});
EOF
cat >> test/issue.test.js <<'EOF'

test('emissão isenta cliente com contrato legado', () => {
  const invoice = issueInvoice('c-300', [{ sku: 'A', quantity: 1, unitCents: 1000 }], '2026-11-01T10:00:00.000Z');
  assert.equal(invoice.serviceFeeCents, 0);
});
EOF
